def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 4:
                rich_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        return min(budget, 20)

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    base = 28 + 18 * scarcity

    if supply >= 22:
        base -= 6
    elif supply <= 17:
        base += 8

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        target = max(avg_prev + 1.0, highest_prev * 0.92 + 1.5)
        base = max(base, target)
        if highest_prev >= 60:
            if hp > 4 and no_water_days == 0:
                base = min(base, 30)
            else:
                base = max(base, 61)
    else:
        if day == 1:
            base = 34 if supply >= 20 else 40

    if urgent_opp >= 2:
        base += 4
    if rich_opp >= 2:
        base += 3

    if hp <= 2:
        base = max(base, 63)
    elif hp <= 4:
        base += 10

    if no_water_days >= 2:
        base = max(base, 66)
    elif no_water_days == 1:
        base += 12

    days_left = max(1, 10 - day + 1)
    reserve_floor = max(0, (days_left - 1) * 18)
    affordable = max(0, budget - reserve_floor)

    if hp <= 3 or no_water_days >= 1:
        bid = min(budget, max(base, affordable * 0.9 if affordable > 0 else base))
    else:
        bid = min(budget, min(base, max(22, affordable)))

    if bid < 0:
        bid = 0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = day_context['day']

    budget = float(my_status['budget'])
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # Collect yesterday bids from immediate previous_trace only
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Safety cap: never bid more than budget
    if budget <= 0:
        return 0

    # Base bid target depends on our urgency
    # If we've already been without water, increase urgency.
    urgency = 0
    if no_water_days >= 2:
        urgency = 2
    elif no_water_days == 1:
        urgency = 1

    # If our HP is low, we must secure water.
    hp_pressure = 0
    if hp <= 2:
        hp_pressure = 3
    elif hp <= 3:
        hp_pressure = 2
    elif hp <= 5:
        hp_pressure = 1

    # Competitive response to opponent yesterday aggressiveness
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))

        # If they were bidding very high, they likely needed water badly.
        if highest_prev_bid >= 0.85 * DAILY_SALARY:
            # Bid to beat them, but avoid full budget burn unless critical.
            if hp_pressure >= 3 or urgency >= 2:
                bid = min(budget, highest_prev_bid + 5.0)
            else:
                bid = min(budget, max(highest_prev_bid + 1.5, 0.65 * DAILY_SALARY))
        # If they were moderate, match around their average plus a small edge.
        elif highest_prev_bid >= 0.45 * DAILY_SALARY:
            bid = min(budget, max(highest_prev_bid + 0.5, avg_prev_bid + 2.0))
        else:
            # They were relaxed; conserve budget and bid at a modest level.
            # Ensure we still try to get water if supply is not too high.
            if supply <= 18.0:
                bid = min(budget, 0.55 * DAILY_SALARY + 5.0 * urgency + 3.0 * hp_pressure)
            else:
                bid = min(budget, 0.45 * DAILY_SALARY + 4.0 * urgency + 2.0 * hp_pressure)
    else:
        # No trace info: choose a budget-aware starting bid.
        if hp_pressure >= 3 or urgency >= 2:
            bid = min(budget, 0.85 * DAILY_SALARY)
        elif hp_pressure >= 2 or urgency >= 1:
            bid = min(budget, 0.65 * DAILY_SALARY)
        else:
            # Light bid to preserve budget early.
            if day <= 3:
                bid = min(budget, 0.50 * DAILY_SALARY)
            else:
                bid = min(budget, 0.55 * DAILY_SALARY)

    # Additional adjustment based on supply: lower supply -> more likely competition.
    if supply <= 16.0:
        bid = min(budget, bid + 8.0)
    elif supply >= 23.0:
        bid = max(0.0, bid - 6.0)

    # Final clamp
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return bid
